<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Blank Canvas</title>
  <style>
    :root {
      color-scheme: dark;
      --ink: #f7f3ea;
      --muted: #b7b0a5;
      --line: rgba(247, 243, 234, .16);
      --glow: #e8a87c;
      --bg: #171614;
    }

    * { box-sizing: border-box; }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      overflow: hidden;
      color: var(--ink);
      background: var(--bg);
      font: 16px/1.5 system-ui, sans-serif;
    }

    body::before {
      content: "";
      position: fixed;
      inset: -25vmax;
      z-index: -1;
      background:
        radial-gradient(circle at 30% 25%, rgba(232, 168, 124, .18), transparent 28%),
        radial-gradient(circle at 72% 75%, rgba(117, 157, 145, .16), transparent 30%);
      filter: blur(30px);
    }

    main {
      width: min(680px, calc(100% - 40px));
      padding: clamp(28px, 7vw, 72px);
      border: 1px solid var(--line);
      border-radius: 28px;
      background: rgba(23, 22, 20, .62);
      box-shadow: 0 24px 100px rgba(0, 0, 0, .28);
      backdrop-filter: blur(14px);
    }

    .eyebrow {
      margin: 0 0 28px;
      color: var(--glow);
      font-size: .75rem;
      font-weight: 700;
      letter-spacing: .18em;
      text-transform: uppercase;
    }

    h1 {
      max-width: 11ch;
      margin: 0;
      font: 400 clamp(3.5rem, 11vw, 7rem)/.92 Georgia, serif;
      letter-spacing: -.06em;
    }

    p {
      max-width: 38ch;
      margin: 30px 0 36px;
      color: var(--muted);
      font-size: clamp(1rem, 2vw, 1.15rem);
    }

    button {
      padding: 12px 17px;
      border: 1px solid var(--line);
      border-radius: 999px;
      color: var(--ink);
      background: transparent;
      font: inherit;
      cursor: pointer;
      transition: border-color .2s, background .2s, transform .2s;
    }

    button:hover, button:focus-visible {
      border-color: var(--glow);
      background: rgba(232, 168, 124, .12);
      outline: none;
      transform: translateY(-2px);
    }

    footer {
      margin-top: 54px;
      padding-top: 15px;
      border-top: 1px solid var(--line);
      color: var(--muted);
      font-size: .8rem;
    }
  </style>
</head>
<body>
  <main>
    <p class="eyebrow">A little room to begin</p>
    <h1>Blank canvas.</h1>
    <p id="prompt">You do not need a grand plan. Put one small, honest thing here.</p>
    <button id="shuffle" type="button">Give me a nudge ↗</button>
    <footer>Made for the moment before the first step.</footer>
  </main>

  <script>
    const prompts = [
      'Make the smallest version that could still be interesting.',
      'Name one thing you keep postponing, then give it ten minutes.',
      'Collect three beautiful details from the room you are in.',
      'Write the sentence you wish someone had told you today.',
      'Follow your curiosity before you try to make it useful.'
    ];

    const prompt = document.querySelector('#prompt');
    document.querySelector('#shuffle').addEventListener('click', () => {
      const current = prompt.textContent;
      const choices = prompts.filter((item) => item !== current);
      prompt.textContent = choices[Math.floor(Math.random() * choices.length)];
    });
  </script>
</body>
</html>
